def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A full beam is defined by matching markers on opposite borders.
    ray_rows = {r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1}
    ray_cols = {c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1}

    # Markers project lines; an object touched by a projected line is recolored
    # in full, while the projected line itself is also colored.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if any(y in ray_rows or x in ray_cols for y, x in component):
                for y, x in component:
                    out[y][x] = 1

    for r in ray_rows:
        for c in range(w):
            out[r][c] = 1
    for c in ray_cols:
        for r in range(h):
            out[r][c] = 1
    return out
